{"query": "
-- Create the available_films table
CREATE TABLE IF NOT EXISTS available_films (
    film_id     INTEGER         PRIMARY KEY,
    title       VARCHAR(255)    NOT NULL,
    rental_rate NUMERIC(4,2)    NOT NULL,
    length      SMALLINT
);
"}

{"query": "
-- Create the film_inventory_summary table
CREATE TABLE IF NOT EXISTS film_inventory_summary (
    title           VARCHAR(255)    NOT NULL,
    rental_rate     NUMERIC(4,2)    NOT NULL,
    total_inventory INTEGER         NOT NULL,
    store1_count    INTEGER         NOT NULL,
    store2_count    INTEGER         NOT NULL
);
"}

{"query": "
-- Also check our new films appear correctly in the summary
SELECT title, rental_rate, total_inventory, store1_count, store2_count
FROM film_inventory_summary
WHERE title IN ('Data Science Adventures', 'Cloud Computing Chronicles');
"}
